const readGameAssetVersion = `-- name: ReadGameAssetVersion :one
SELECT a.id, a.game_id, a.game_source_id, a.platform_code, a.external_key, a.kind, a.category, a.source_family, a.source_role, a.source_identity,v.id, v.game_id, v.asset_id, v.binding_id, v.observation_id, v.scope_key, v.egress_region, v.locale, v.origin, v.name, v.original_order, v.highlight, v.truncated,l.selected_at,
 (s.active AND b.effective_until IS NULL AND EXISTS (
   SELECT 1 FROM game_source_media m WHERE m.game_source_id=a.game_source_id AND m.binding_id=v.binding_id AND m.observation_id=v.observation_id
    AND m.scope_key=v.scope_key AND m.egress_region=v.egress_region AND m.state='present'
 ))::boolean AS current
FROM game_asset_versions v JOIN game_assets a ON a.id=v.asset_id JOIN game_sources s ON s.id=a.game_source_id
JOIN collection_bindings b ON b.id=v.binding_id
LEFT JOIN game_asset_library l ON l.game_id=v.game_id AND l.version_id=v.id
WHERE v.game_id=$1 AND a.id=$2 AND v.id=$3
`

type ReadGameAssetVersionParams struct {
	GameID    uuid.UUID `json:"game_id"`
	AssetID   uuid.UUID `json:"asset_id"`
	VersionID uuid.UUID `json:"version_id"`
}

type ReadGameAssetVersionRow struct {
	GameAsset        GameAsset          `json:"game_asset"`
	GameAssetVersion GameAssetVersion   `json:"game_asset_version"`
	SelectedAt       pgtype.Timestamptz `json:"selected_at"`
	Current          bool               `json:"current"`
}

func (q *Queries) ReadGameAssetVersion(ctx context.Context, arg ReadGameAssetVersionParams) (ReadGameAssetVersionRow, error) {
	row := q.db.QueryRow(ctx, readGameAssetVersion, arg.GameID, arg.AssetID, arg.VersionID)
	var i ReadGameAssetVersionRow
	err := row.Scan(
		&i.GameAsset.ID,
		&i.GameAsset.GameID,
		&i.GameAsset.GameSourceID,
		&i.GameAsset.PlatformCode,
		&i.GameAsset.ExternalKey,
		&i.GameAsset.Kind,
		&i.GameAsset.Category,
		&i.GameAsset.SourceFamily,
		&i.GameAsset.SourceRole,
		&i.GameAsset.SourceIdentity,
		&i.GameAssetVersion.ID,
		&i.GameAssetVersion.GameID,
		&i.GameAssetVersion.AssetID,
		&i.GameAssetVersion.BindingID,
		&i.GameAssetVersion.ObservationID,
		&i.GameAssetVersion.ScopeKey,
		&i.GameAssetVersion.EgressRegion,
		&i.GameAssetVersion.Locale,
		&i.GameAssetVersion.Origin,
		&i.GameAssetVersion.Name,
		&i.GameAssetVersion.OriginalOrder,
		&i.GameAssetVersion.Highlight,
		&i.GameAssetVersion.Truncated,
		&i.SelectedAt,
		&i.Current,
	)
	return i, err
}

